  function timeValues(record,basis='interaction',sources){if(basis==='created')return record.createdAt?[record.createdAt]:[];if(basis==='captured')return record.capturedAt?[record.capturedAt]:[];const fields=['likes','bookmarks'].includes(basis)?[basis]:(sources?.length?sources:['likes','bookmarks']);return fields.filter(s=>record.interactionTimes?.[s]?.active!==false).map(s=>record.interactionTimes?.[s]?.at).filter(Boolean);}
  function timeRangeBounds(range={}){function parseDay(day){if(!/^\d{4}-\d{2}-\d{2}$/.test(day))throw new Error('时间段日期格式无效');const check=new Date(day+'T00:00:00Z');if(!Number.isFinite(check.getTime())||check.toISOString().slice(0,10)!==day)throw new Error('时间段包含无效日期');return new Date(day+'T00:00:00+08:00').getTime();}const start=range.from?parseDay(range.from):-Infinity,end=range.to?parseDay(range.to)+86400000:Infinity;if(start>=end)throw new Error('开始日期应早于或等于结束日期');return {start,end};}
