    get('reader-clear').addEventListener('click',()=>{get('reader-search').value='';get('reader-media').value='all';get('reader-from').value='';get('reader-to').value='';get('reader-unknown').checked=false;apply();});get('reader-layout').addEventListener('click',()=>{view=view==='cards'?'timeline':'cards';get('reader-layout').textContent=view==='cards'?'切换时间线':'切换列表';apply();});get('reader-expand').addEventListener('click',()=>{const details=cards.filter(c=>!c.hidden).map(c=>c.querySelector('details')).filter(Boolean);const open=details.some(d=>!d.open);for(const d of details)d.open=open;get('reader-expand').textContent=open?'收起正文':'展开正文';});get('reader-print').addEventListener('click',()=>window.print());
